use tracing_subscriber::prelude::*;
use tracing_subscriber::registry::LookupSpan;
use tracing_subscriber::EnvFilter;

#[derive(Default)]
struct Rec {
    target: String,
    fields: Vec<String>,
}

struct Cap(Arc<Mutex<Vec<Rec>>>);

struct V<'a>(&'a mut Rec);
impl Visit for V<'_> {
    fn record_debug(&mut self, f: &Field, v: &dyn std::fmt::Debug) {
        self.0.fields.push(format!("{}={:?}", f.name(), v));
    }
}

impl<S: Subscriber + for<'l> LookupSpan<'l>> Layer<S> for Cap {
    fn on_event(&self, ev: &tracing::Event<'_>, _c: Context<'_, S>) {
        let mut r = Rec {
            target: ev.metadata().target().to_owned(),
            fields: vec![],
        };
        ev.record(&mut V(&mut r));
        self.0.lock().unwrap().push(r);
    }
}

fn main() {
    // Part A: what does each form actually produce?
    let cap = Arc::new(Mutex::new(Vec::new()));
    let sub = tracing_subscriber::registry().with(Cap(cap.clone()));
    tracing::subscriber::with_default(sub, || {
        tracing::warn!(target = "paigasus::openai::translate", "EQUALS form");
        tracing::warn!(target: "paigasus::openai::translate", "COLON form");
    });
    for r in cap.lock().unwrap().iter() {
        println!("metadata.target = {:<40} fields = {:?}", r.target, r.fields);
    }

    // Part B: does an EnvFilter on the claimed target let each through?
    println!("\n-- EnvFilter: paigasus::openai::translate=warn --");
    let cap2 = Arc::new(Mutex::new(Vec::new()));
    let sub2 = tracing_subscriber::registry()
        .with(Cap(cap2.clone()))
        .with(EnvFilter::new("off,paigasus::openai::translate=warn"));
    tracing::subscriber::with_default(sub2, || {
        tracing::warn!(target = "paigasus::openai::translate", "EQUALS form");
        tracing::warn!(target: "paigasus::openai::translate", "COLON form");
    });
    let got = cap2.lock().unwrap();
    println!("events that passed the filter: {}", got.len());
    for r in got.iter() {
        println!("  passed: target={} fields={:?}", r.target, r.fields);
    }
}
